import datetime


def _parse_field(field: str, min_val: int, max_val: int, name_map: dict = None) -> set:
    """Parse a single cron field and return the set of matching values."""
    if name_map is None:
        name_map = {}

    result = set()
    parts = field.split(',')

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError(f"Empty item in field '{field}'")

        # Check for step
        step = 1
        if '/' in part:
            base, step_str = part.split('/', 1)
            step_str = step_str.strip()
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value '{step_str}'")
            if step <= 0:
                raise ValueError("Step must be positive")
        else:
            base = part

        # Parse the base part (could be *, N, or A-B)
        def _resolve(val_str):
            """Resolve a single value string to an integer."""
            val_str = val_str.strip()
            if name_map and val_str.upper() in name_map:
                return name_map[val_str.upper()]
            try:
                return int(val_str)
            except ValueError:
                raise ValueError(f"Invalid value '{val_str}'")

        if base == '*':
            start = min_val
            end = max_val
        elif '-' in base:
            a_str, b_str = base.split('-', 1)
            a = _resolve(a_str)
            b = _resolve(b_str)
            if a > b:
                raise ValueError(f"Range start {a} greater than end {b}")
            if a < min_val or b > max_val:
                raise ValueError(f"Range {a}-{b} out of bounds [{min_val}, {max_val}]")
            start = a
            end = b
        else:
            val = _resolve(base)
            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
            if '/' in part:
                # A/S means from A to max
                start = val
                end = max_val
            else:
                start = val
                end = val

        for v in range(start, end + 1, step):
            result.add(v)

    return result


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """Find the next fire time for a standard 5-field cron expression."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    day_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    try:
        minutes = _parse_field(fields[0], 0, 59)
        hours = _parse_field(fields[1], 0, 23)
        days_of_month = _parse_field(fields[2], 1, 31)
        months = _parse_field(fields[3], 1, 12, month_names)
        # For day-of-week, map 7 to 0 (both Sunday)
        dow_raw = _parse_field(fields[4], 0, 7, day_names)
        days_of_week = set()
        for d in dow_raw:
            if d == 7:
                days_of_week.add(0)
            else:
                days_of_week.add(d)
    except ValueError as e:
        raise ValueError(f"Error parsing cron expression: {e}")

    # Check for empty sets (shouldn't happen with valid input, but just in case)
    if not minutes or not hours or not days_of_month or not months or not days_of_week:
        raise ValueError("Parsed field resulted in empty set")

    # Determine if day fields are restricted
    dom_restricted = fields[2].strip() != '*'
    dow_restricted = fields[4].strip() != '*'

    # Start from the next minute after 'after'
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # Limit search to 5 years
    limit = current + datetime.timedelta(days=366 * 5)

    while current < limit:
        if current.year > after.year + 5 or (current.year == after.year + 5 and current.month > after.month):
            break

        # Check month
        if current.month not in months:
            # Advance to the first day of the next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1)
            else:
                current = current.replace(month=current.month + 1, day=1)
            current = current.replace(hour=0, minute=0)
            continue

        # Check day (Vixie cron logic)
        dom_match = current.day in days_of_month
        # Convert Python's weekday() to cron's day-of-week (0=Sunday)
        py_weekday = current.weekday()  # 0=Monday, 6=Sunday
        cron_dow = (py_weekday + 1) % 7  # 0=Sunday, 1=Monday, ..., 6=Saturday
        dow_match = cron_dow in days_of_week

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if not day_ok:
            # Advance to next day
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if current.hour not in hours:
            # Find the next valid hour today
            valid_hours = sorted(h for h in hours if h > current.hour)
            if valid_hours:
                current = current.replace(hour=valid_hours[0], minute=0)
            else:
                # Move to next day
                current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check minute
        if current.minute not in minutes:
            # Find the next valid minute in this hour
            valid_minutes = sorted(m for m in minutes if m > current.minute)
            if valid_minutes:
                current = current.replace(minute=valid_minutes[0])
            else:
                # Move to next hour
                if current.hour < 23:
                    current = (current + datetime.timedelta(hours=1)).replace(minute=0)
                else:
                    current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # All fields match
        return current

    raise ValueError("No matching time found within 5 years")
