def merge(base: dict, *overrides: dict) -> dict:
    """Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends items to the base list (missing base -> new list).
      If the base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs must not be mutated; result is a deep copy with no shared mutable containers.
    """

    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        else:
            return obj

    def _merge_into(base_dict: dict, override_dict: dict) -> dict:
        """Merge override_dict into base_dict (both dicts), returning a new dict.

        This handles the recursive merging and special key rules.
        """
        result = _deep_copy(base_dict)

        for key, value in override_dict.items():
            if key.endswith('+'):
                # Append semantics
                target_key = key[:-1]
                append_value = value

                if target_key in result:
                    existing = result[target_key]
                    if not isinstance(existing, list):
                        raise TypeError(
                            f"Key '{target_key}' has a non-list value "
                            f"(type {type(existing).__name__}), cannot append to it."
                        )
                    # Append deep copies of items from append_value
                    if isinstance(append_value, list):
                        for item in append_value:
                            existing.append(_deep_copy(item))
                    else:
                        # If append_value is not a list, wrap it? The spec says "appends the items"
                        # Let's assume append_value should be iterable. But to be safe, if it's a single value,
                        # we can just append it. However, the example shows a list.
                        # Let's treat non-list as a single item to append.
                        existing.append(_deep_copy(append_value))
                else:
                    # Missing base -> new list
                    if isinstance(append_value, list):
                        result[target_key] = _deep_copy(append_value)
                    else:
                        result[target_key] = [_deep_copy(append_value)]
            elif value is None:
                # Delete key from result
                if key in result:
                    del result[key]
            elif isinstance(value, dict):
                # Recursive merge
                if key in result and isinstance(result[key], dict):
                    result[key] = _merge_into(result[key], value)
                else:
                    # Replace with deep copy of the override dict
                    result[key] = _deep_copy(value)
            else:
                # Replace base value with deep copy of override value
                result[key] = _deep_copy(value)

        return result

    # Start with a deep copy of base
    result = _deep_copy(base)

    # Apply each override in order
    for override in overrides:
        result = _merge_into(result, override)

    return result
