def parse_duration(s: str) -> int:
    """Parse a duration string like '1h30m' or '2d 4h' into seconds."""
    if not s:
        raise ValueError("Empty input")

    # Allowed units in order
    unit_order = ['d', 'h', 'm', 's']
    unit_seconds = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    # Split by spaces and validate each token
    tokens = s.split(' ')

    # Check for empty tokens (would indicate multiple spaces or leading/trailing space)
    for i, token in enumerate(tokens):
        if not token:
            raise ValueError("Invalid format: empty token")

    total_seconds = 0
    last_unit_index = -1

    for token in tokens:
        # Each token must be <integer><unit>
        # Find where digits end and unit begins
        j = 0
        while j < len(token) and token[j].isdigit():
            j += 1

        if j == 0:
            raise ValueError("Missing number")

        if j >= len(token):
            raise ValueError("Missing unit")

        # The rest of the token should be exactly one character, a valid unit
        if len(token) - j != 1:
            raise ValueError(f"Invalid token: {token}")

        unit_char = token[j].lower()

        if unit_char not in unit_seconds:
            raise ValueError(f"Unknown unit: {unit_char}")

        unit_idx = unit_order.index(unit_char)

        # Check order and repetition
        if unit_idx <= last_unit_index:
            raise ValueError("Wrong order or repeated unit")
        last_unit_index = unit_idx

        total_seconds += int(token[:j]) * unit_seconds[unit_char]

    return total_seconds


def format_duration(seconds: int) -> str:
    """Format seconds into a canonical duration string like '1h30m'."""
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    unit_values = [
        ('d', 86400),
        ('h', 3600),
        ('m', 60),
        ('s', 1),
    ]

    parts = []
    remaining = seconds
    for unit, val in unit_values:
        count = remaining // val
        if count > 0:
            parts.append(f"{count}{unit}")
        remaining %= val

    return ''.join(parts)
