        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)

            if _is_index(part):
                idx = int(part)

                # Check if current is a list or dict
                if isinstance(current, dict):
                    # This means we're at a dict but encountering an index segment
                    # The key "0" in a dict is valid - it's just a string key "0"
                    # But wait - the spec says non-negative integer segments create lists.
                    # So if part looks like an index, it should be treated as list index.
                    # But root must be a dict... contradiction?
                    # 
                    # Actually re-reading: "a path segment that is a non-negative integer
                    # without leading zeros creates a list". This means the *container*
                    # for that segment is a list. So if we have key "0", the top-level
                    # should be a list with index 0? But flatten requires top-level dict.
                    #
                    # I think the resolution is: in unflatten, if a segment is an index,
                    # the parent must be (or become) a list. For the root, since flatten
                    # always produces a dict, the first segment can never be an index that
                    # makes root a list. So "0" as a key in flat means it's a dict key "0".
                    #
                    # But that contradicts the spec... Let me re-read.
                    #
                    # Actually I think the intent is: when unflattening, if a segment parses
                    # as an integer, it indexes into a list. So {"0": 1} would create [1].
                    # But then flatten([1]) would give {"0": 1}, and unflatten({"0": 1}) = [1],
                    # which is not the inverse of flatten since flatten requires dict input.
                    #
                    # The round-trip property only holds for dicts. So unflatten can produce
                    # lists at any level, including top-level? But the spec says flatten's
                    # top-level must be a dict. I think unflatten should also assume the
                    # result is a dict (inverse of flatten).
                    #
                    # Let me just follow the spec literally: index segments create lists.
                    # If root would need to be a list, that's fine - unflatten can return
                    # anything. But for round-trip with flatten, we'll have dicts at top.

                    raise ValueError(f"Expected list but found dict at segment {part!r} in key {key!r}")
                else:  # current is a list
                    while len(current) <= idx:
                        current.append(None)

                    if is_last:
                        current[idx] = value
                    else:
                        node = current[idx]
                        if node is None:
                            next_part = parts[i + 1]
                            if _is_index(next_part):
                                current[idx] = []
                            else:
                                current[idx] = {}
                            current = current[idx]
                        elif isinstance(node, (dict, list)):
                            current = node
                        else:
                            raise ValueError(f"Conflict at key: {key!r}")
            else:
                # Not an index - must be a dict key
                if not isinstance(current, dict):
                    raise ValueError(f"Expected dict but found list at segment {part!r} in key {key!r}")

                if is_last:
                    current[part] = value
                else:
                    if part not in current:
                        next_part = parts[i + 1]
                        if _is_index(next_part):
                            current[part] = []
                        else:
                            current[part] = {}
                    node = current[part]
                    if isinstance(node, (dict, list)):
                        current = node
                    else:
                        raise ValueError(f"Conflict at key: {key!r}")

    # Post-process to validate dense lists
    def _validate(o):
        if isinstance(o, dict):
            for k in o:
                v = o[k]
                if isinstance(v, (dict, list)):
                    _validate(v)
                elif v is None:
                    raise ValueError("Invalid structure: unfilled placeholder")
        elif isinstance(o, list):
            for i in range(len(o)):
                if o[i] is None:
                    raise ValueError(f"List has gap at index {i}")
                if isinstance(o[i], (dict, list)):
                    _validate(o[i])

    _validate(root)
    return root
