```python
"""A small expression language interpreter.

Grammar (lowest to highest precedence):
1. a ? b : c          conditional, right-associative
2. ||                 logical or  (short-circuit)
3. &&                 logical and (short-circuit)
4. == != < <= > >=    comparisons (non-associative)
5. + -                additive (left-assoc)
6. * / %              multiplicative (left-assoc)
7. unary - + !        unary operators
8. ^                  power (right-assoc, binds tighter than unary minus on left)
9. atoms: int/float literals, identifiers, function calls, parentheses
"""

from __future__ import annotations


class _Token:
    def __init__(self, kind: str, value=None, pos: int = 0):
        self.kind = kind      # 'NUM', 'IDENT', 'OP', 'EOF'
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r})"


def _tokenize(s: str) -> list[_Token]:
    tokens: list[_Token] = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        # Numbers
        if c.isdigit() or (c == '.' and i + 1 < n and s[i + 1].isdigit()):
            start = i
            is_float = False
            if c == '.':
                is_float = True
                i += 1
            else:
                while i < n and s[i].isdigit():
                    i += 1
            if i < n and s[i] == '.':
                is_float = True
                i += 1
                while i < n and s[i].isdigit():
                    i += 1
            text = s[start:i]
            if is_float:
                tokens.append(_Token('NUM', float(text), start))
            else:
                tokens.append(_Token('NUM', int(text), start))
            continue
        # Identifiers / function names
        if c.isalpha() or c == '_':
            start = i
            while i < n and (s[i].isalnum() or s[i] == '_'):
                i += 1
            tokens.append(_Token('IDENT', s[start:i], start))
            continue
        # Two-char operators
        if i + 1 < n:
            two = s[i:i + 2]
            if two in ('==', '!=', '<=', '>=', '||', '&&'):
                tokens.append(_Token('OP', two, i))
                i += 2
                continue
        # Single-char operators / punctuation
        if c in '+-*/%^!<>?:()':
            tokens.append(_Token('OP', c, i))
            i += 1
            continue
        raise SyntaxError(f"Unexpected character {c!r} at position {i}")
    tokens.append(_Token('EOF', None, i))
    return tokens


class _Parser:
    def __init__(self, tokens: list[_Token], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self) -> _Token:
        return self.tokens[self.pos]

    def advance(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect_op(self, op: str) -> _Token:
        tok = self.peek()
        if tok.kind != 'OP' or tok.value != op:
            raise SyntaxError(f"Expected {op!r} but got {tok!r}")
        return self.advance()

    def match_op(self, op: str) -> bool:
        tok = self.peek()
        if tok.kind == 'OP' and tok.value == op:
            self.advance()
            return True
        return False

    # --- Expression levels (lowest to highest precedence) ---

    def parse_expr(self):
        """Level 1: conditional a ? b : c (right-associative)"""
        left = self.parse_or()
        if self.match_op('?'):
            middle = self.parse_expr()  # right-associative: parse full expr for the true branch
            self.expect_op(':')
            right = self.parse_expr()   # false branch
            return ('cond', left, middle, right)
        return left

    def parse_or(self):
        """Level 2: || (left-assoc, short-circuit)"""
        left = self.parse_and()
        while self.match_op('||'):
            right = self.parse_and()
            left = ('or', left, right)
        return left

    def parse_and(self):
        """Level 3: && (left-assoc, short-circuit)"""
        left = self.parse_comparison()
        while self.match_op('&&'):
            right = self.parse_comparison()
            left = ('and', left, right)
        return left

    def parse_comparison(self):
        """Level 4: == != < <= > >= (non-associative)"""
        left = self.parse_additive()
        tok = self.peek()
        if tok.kind == 'OP' and tok.value in ('==', '!=', '<', '<=', '>', '>='):
            op = self.advance().value
            right = self.parse_additive()
            # Non-associative: the next token must not be another comparison operator
            nxt = self.peek()
            if nxt.kind == 'OP' and nxt.value in ('==', '!=', '<', '<=', '>', '>='):
                raise SyntaxError(f"Non-associative comparison at position {nxt.pos}")
            return ('cmp', op, left, right)
        return left

    def parse_additive(self):
        """Level 5: + - (left-assoc)"""
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok.kind == 'OP' and tok.value in ('+', '-'):
                op = self.advance().value
                right = self.parse_multiplicative()
                left = ('binop', op, left, right)
            else:
                break
        return left

    def parse_multiplicative(self):
        """Level 6: * / % (left-assoc)"""
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok.kind == 'OP' and tok.value in ('*', '/', '%'):
                op = self.advance().value
                right = self.parse_unary()
                left = ('binop', op, left, right)
            else:
                break
        return left

    def parse_unary(self):
        """Level 7: unary - + !"""
        tok = self.peek()
        if tok.kind == 'OP' and tok.value in ('-', '+', '!'):
            op = self.advance().value
            operand = self.parse_power()
            return ('unary', op, operand)
        return self.parse_power()

    def parse_power(self):
        """Level 8: ^ (right-assoc). Binds tighter than unary minus on its left.
        So -2^2 is -(2^2) = -4, and 2^-1 is 2^(-1) = 0.5."""
        base = self.parse_atom()
        tok = self.peek()
        if tok.kind == 'OP' and tok.value == '^':
            self.advance()
            # Right-associative: the exponent is a unary expression (to allow 2^-1)
            exponent = self.parse_unary()
            return ('binop', '^', base, exponent)
        return base

    def parse_atom(self):
        """Level 9: atoms - numbers, identifiers, function calls, parentheses."""
        tok = self.peek()
        if tok.kind == 'EOF':
            raise SyntaxError("Unexpected end of input")

        if tok.kind == 'NUM':
            self.advance()
            return ('num', tok.value)

        if tok.kind == 'IDENT':
            name = self.advance().value
            nxt = self.peek()
            if nxt.kind == 'OP' and nxt.value == '(':
                # Function call
                self.advance()  # consume '('
                args: list = []
                if not (self.peek().kind == 'OP' and self.peek().value == ')'):
                    while True:
                        args.append(self.parse_expr())
                        if self.match_op(','):
                            continue
                        break
                self.expect_op(')')
                return ('call', name, args)
            else:
                return ('var', name)

        if tok.kind == 'OP' and tok.value == '(':
            self.advance()  # consume '('
            node = self.parse_expr()
            self.expect_op(')')
            return node

        raise SyntaxError(f"Unexpected token {tok!r} at position {tok.pos}")


def _eval(node, env: dict[str, float]) -> int | float:
    tag = node[0]

    if tag == 'num':
        return node[1]

    if tag == 'var':
        name = node[1]
        if name not in env:
            raise NameError(f"name '{name}' is not defined")
        return env[name]

    if tag == 'call':
        name = node[1]
        args = [_eval(a, env) for a in node[2]]
        if name == 'min':
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            return min(args)
        elif name == 'max':
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            return max(args)
        elif name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"function '{name}' is not defined")

    if tag == 'unary':
        op = node[1]
        val = _eval(node[2], env)
        if op == '-':
            return -val
        elif op == '+':
            return +val
        elif op == '!':
            return 1 if val == 0 else 0

    if tag == 'binop':
        op = node[1]
        left_val = _eval(node[2], env)
        right_val = _eval(node[3], env)
        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            if right_val == 0:
                raise ZeroDivisionError("division by zero")
            if isinstance(left_val, int) and isinstance(right_val, int):
                if left_val % right_val == 0:
                    return left_val // right_val
                else:
                    return left_val / right_val
            else:
                return left_val / right_val
        elif op == '%':
            if right_val == 0:
                raise ZeroDivisionError("modulo by zero")
            return left_val % right_val
        elif op == '^':
            return left_val ** right_val

    if tag == 'cmp':
        op = node[1]
        left_val = _eval(node[2], env)
        right_val = _eval(node[3], env)
        if op == '==':
            return 1 if left_val == right_val else 0
        elif op == '!=':
            return 1 if left_val != right_val else 0
        elif op == '<':
            return 1 if left_val < right_val else 0
        elif op == '<=':
            return 1 if left_val <= right_val else 0
        elif op == '>':
            return 1 if left_val > right_val else 0
        elif op == '>=':
            return 1 if left_val >= right_val else 0

    if tag == 'and':
        left_val = _eval(node[1], env)
        if left_val == 0:
            return 0
        right_val = _eval(node[2], env)
        return 1 if right_val != 0 else 0

    if tag == 'or':
        left_val = _eval(node[1], env)
        if left_val != 0:
            return 1
        right_val = _eval(node[2], env)
        return 1 if right_val != 0 else 0

    if tag == 'cond':
        cond_val = _eval(node[1], env)
        if cond_val != 0:
            return _eval(node[2], env)
        else:
            return _eval(node[3], env)

    raise SyntaxError(f"Unknown node type: {tag}")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """Evaluate an expression string in the small expression language.

    Args:
        expr: The expression string to evaluate.
        env: A dictionary mapping variable names to numeric values.

    Returns:
        The result of evaluating the expression (int or float).

    Raises:
        SyntaxError: For malformed expressions.
        NameError: For undefined variables or functions.
        ZeroDivisionError: For division or modulo by zero.
    """
    if not expr.strip():
        raise SyntaxError("Empty input")

    tokens = _tokenize(expr)
    parser = _Parser(tokens, env)
    tree = parser.parse_expr()
    # Check for trailing tokens
    tok = parser.peek()
    if tok.kind != 'EOF':
        raise SyntaxError(f"Unexpected token {tok!r} at position {tok.pos}")

    return _eval(tree, env)
