import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        # Ignore empty intervals
        if start >= end:
            return

        new_intervals = []
        cur_start = start
        cur_end = end
        added = False

        for s, e in self._iv:
            # If the current interval is strictly before the one we are adding
            # (no overlap and no touching)
            if e < cur_start:
                new_intervals.append((s, e))
            # If the current interval is strictly after the one we are adding
            elif s > cur_end:
                if not added:
                    new_intervals.append((cur_start, cur_end))
                    added = True
                new_intervals.append((s, e))
            else:
                # Overlap or touch: merge them
                cur_start = min(cur_start, s)
                cur_end = max(cur_end, e)

        if not added:
            new_intervals.append((cur_start, cur_end))

        self._iv = new_intervals

    def remove(self, start, end):
        # Ignore empty intervals
        if start >= end:
            return

        new_intervals = []
        for s, e in self._iv:
            # If no overlap, keep it
            if e <= start or s >= end:
                new_intervals.append((s, e))
            else:
                # Overlap exists
                # Add left part if it exists
                if s < start:
                    new_intervals.append((s, start))
                # Add right part if it exists
                if e > end:
                    new_intervals.append((end, e))

        self._iv = new_intervals

    def contains(self, x):
        for s, e in self._iv:
            if s <= x < e:
                return True
            # Optimization: since sorted by start, if current start is > x, 
            # no subsequent interval can contain x
            if s > x:
                break
        return False

    def free(self, lo, hi):
        gaps = []
        cur = lo
        for s, e in self._iv:
            # Only consider intervals that overlap with [lo, hi)
            if e <= lo or s >= hi:
                continue

            if s > cur:
                gaps.append((cur, s))
            cur = max(cur, e)

        if cur < hi:
            gaps.append((cur, hi))

        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
