```python
def route(grid: list[str]) -> tuple[int, str] | None:
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0])

    # Validate grid
    s_count = 0
    e_count = 0
    pad_counts = {}

    for r in range(rows):
        if len(grid[r]) != cols:
            raise ValueError("Ragged rows")
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                s_count += 1
            elif ch == 'E':
                e_count += 1
            elif ch == '#' or ch == '.':
                pass
            elif ch.isdigit() and '1' <= ch <= '9':
                pass
            elif ch.islower():
                pad_counts[ch] = pad_counts.get(ch, 0) + 1
            else:
                raise ValueError(f"Unknown character: {ch}")

    if s_count != 1 or e_count != 1:
        raise ValueError("Must have exactly one S and one E")

    for ch, count in pad_counts.items():
        if count == 1 or count > 2:
            raise ValueError(f"Pad {ch} appears {count} times, must be 0 or 2")

    # Find start and end positions
    start = None
    end = None
    pads = {}  # letter -> list of (r, c)

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                start = (r, c)
            elif ch == 'E':
                end = (r, c)
            elif ch.islower():
                if ch not in pads:
                    pads[ch] = []
                pads[ch].append((r, c))

    def get_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif ch.isdigit() and '1' <= ch <= '9':
            return int(ch)
        elif ch.islower():
            return 1
        else:
            return None

    # Dijkstra's algorithm with lexicographic tie-breaking
    # State: (r, c)
    # We want to find the cheapest path from S to E.
    # Among all cheapest paths, we want the lexicographically smallest move string.
    # Move order for lex comparison: D < L < R < T < U

    import heapq

    # dist[r][c] = minimum cost to reach (r,c)
    # best_path[r][c] = lexicographically smallest path string among those with minimum cost
    dist = [[float('inf')] * cols for _ in range(rows)]
    best_path = [['' for _ in range(cols)] for _ in range(rows)]

    start_r, start_c = start
    end_r, end_c = end

    dist[start_r][start_c] = 0
    best_path[start_r][start_c] = ""

    # Priority queue: (cost, path_string, r, c)
    # We use the path string for tie-breaking in the heap
    heap = [(0, "", start_r, start_c)]

    while heap:
        cost, path, r, c = heapq.heappop(heap)

        if cost > dist[r][c]:
            continue

        if (r, c) == end:
            return (cost, path)

        # Try all moves in lex order: D, L, R, T, U
        moves = []

        # D: down
        nr, nc = r + 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if mc is not None:
                moves.append(('D', nr, nc, mc))

        # L: left
        nr, nc = r, c - 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if mc is not None:
                moves.append(('L', nr, nc, mc))

        # R: right
        nr, nc = r, c + 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if mc is not None:
                moves.append(('R', nr, nc, mc))

        # T: teleport (if on a pad)
        ch = grid[r][c]
        if ch.islower() and ch in pads:
            pad_positions = pads[ch]
            for pr, pc in pad_positions:
                if (pr, pc) != (r, c):
                    moves.append(('T', pr, pc, 2))

        # U: up
        nr, nc = r - 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if mc is not None:
                moves.append(('U', nr, nc, mc))

        for move_char, nr, nc, move_cost in moves:
            new_cost = cost + move_cost
            new_path = path + move_char

            if new_cost < dist[nr][nc]:
                dist[nr][nc] = new_cost
                best_path[nr][nc] = new_path
                heapq.heappush(heap, (new_cost, new_path, nr, nc))
            elif new_cost == dist[nr][nc] and new_path < best_path[nr][nc]:
                best_path[nr][nc] = new_path
                heapq.heappush(heap, (new_cost, new_path, nr, nc))

    return None
