"""npm-style semantic version ranges."""

import re
from dataclasses import dataclass, field
from functools import total_ordering
from typing import List, Optional, Tuple


@total_ordering
@dataclass
class Version:
    major: int
    minor: int
    patch: int
    prerelease: Optional[str] = None
    build: Optional[str] = None

    def __post_init__(self):
        if self.prerelease is not None and self.prerelease == "":
            raise ValueError("Empty prerelease")
        if self.build is not None and self.build == "":
            raise ValueError("Empty build")

    @property
    def key(self) -> tuple:
        """Return a sort key for SemVer precedence comparison."""
        # Build metadata is ignored in precedence
        pre = self.prerelease
        if pre is None:
            # Release version
            pre_key = (1,)  # Releases are greater than prereleases
        else:
            # Prerelease identifiers
            ids = pre.split(".")
            # Each identifier: numeric or alphanumeric
            # Numeric identifiers compare as integers, less than alphanumeric
            # Alphanumeric compare in ASCII order
            # A shorter prefix list is smaller (if all preceding are equal)
            parts = []
            for ident in ids:
                if ident.isdigit():
                    parts.append((0, int(ident), ""))
                else:
                    parts.append((1, 0, ident))
            pre_key = (0, tuple(parts))
        return (self.major, self.minor, self.patch, pre_key)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.key == other.key

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.key < other.key

    def __hash__(self):
        return hash(self.key)

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += f"-{self.prerelease}"
        if self.build is not None:
            s += f"+{self.build}"
        return s


def _parse_identifier(ident: str) -> bool:
    """Check if a prerelease/build identifier is valid."""
    if not ident:
        return False
    # Must be [0-9A-Za-z-]+
    if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
        return False
    # Numeric identifiers must not have leading zeros
    if ident.isdigit() and len(ident) > 1 and ident[0] == '0':
        return False
    return True


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    s = v.strip()
    # Remove leading 'v' or '='
    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    # Split off build metadata
    build = None
    if '+' in s:
        idx = s.index('+')
        build = s[idx + 1:]
        s = s[:idx]
        if not build:
            raise ValueError("Empty build metadata")
        for ident in build.split('.'):
            if not _parse_identifier(ident):
                raise ValueError(f"Invalid build identifier: {ident}")

    # Split off prerelease
    prerelease = None
    if '-' in s:
        idx = s.index('-')
        prerelease = s[idx + 1:]
        s = s[:idx]
        if not prerelease:
            raise ValueError("Empty prerelease")
        for ident in prerelease.split('.'):
            if not _parse_identifier(ident):
                raise ValueError(f"Invalid prerelease identifier: {ident}")

    # Parse MAJOR.MINOR.PATCH
    parts = s.split('.')
    if len(parts) < 1 or len(parts) > 3:
        raise ValueError("Invalid version format")

    def parse_numeric(p: str, name: str) -> int:
        if not p:
            raise ValueError(f"Empty {name}")
        if not p.isdigit():
            raise ValueError(f"{name} must be numeric: {p}")
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zeros in {name}: {p}")
        return int(p)

    major = parse_numeric(parts[0], "MAJOR")
    minor = parse_numeric(parts[1], "MINOR") if len(parts) > 1 else 0
    patch = parse_numeric(parts[2], "PATCH") if len(parts) > 2 else 0

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[str], bool]:
    """Parse a partial version for use in comparators.

    Returns (major, minor, patch, prerelease, is_exact)
    where None means X/wildcard. is_exact indicates if all three numeric parts are specified.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty version in comparator")

    # Remove leading v or =
    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    build = None
    if '+' in s:
        idx = s.index('+')
        build = s[idx + 1:]
        s = s[:idx]
        # Build metadata is not relevant for range matching, but we should validate
        if not build:
            raise ValueError("Empty build metadata")

    prerelease = None
    if '-' in s:
        idx = s.index('-')
        prerelease = s[idx + 1:]
        s = s[:idx]
        if not prerelease:
            raise ValueError("Empty prerelease")

    # Check for x, X, * wildcards
    parts = s.split('.')

    major = None
    minor = None
    patch = None

    def parse_num_or_x(p: str) -> Optional[int]:
        p = p.strip()
        if p in ('x', 'X', '*'):
            return None
        if not p:
            raise ValueError("Empty version part")
        if not p.isdigit():
            raise ValueError(f"Invalid numeric part: {p}")
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zeros: {p}")
        return int(p)

    if len(parts) >= 1:
        major = parse_num_or_x(parts[0])
    if len(parts) >= 2:
        minor = parse_num_or_x(parts[1])
    if len(parts) >= 3:
        patch = parse_num_or_x(parts[2])

    # If any part is X, all subsequent must also be X (or absent)
    if major is None and (minor is not None or patch is not None):
        raise ValueError("Invalid partial version: cannot have specific minor/patch without major")
    if minor is None and patch is not None:
        raise ValueError("Invalid partial version: cannot have specific patch without minor")

    is_exact = major is not None and minor is not None and patch is not None

    return (major, minor, patch, prerelease, is_exact)


class Comparator:
    """A single comparator like >=1.2.3 or ~1.2 or ^1.x etc."""
    def __init__(self, op: str, version: Version, lower_inclusive: bool = True):
        self.op = op  # '<', '<=', '>', '>=', '='
        self.version = version
        self.lower_inclusive = lower_inclusive

    def matches(self, v: Version) -> bool:
        if self.op == '<':
            return v < self.version
        elif self.op == '<=':
            return v <= self.version
        elif self.op == '>':
            return v > self.version
        elif self.op == '>=':
            return v >= self.version
        elif self.op == '=':
            return v == self.version
        else:
            raise ValueError(f"Unknown operator: {self.op}")


class ComparatorSet:
    """A set of comparators that must all match."""
    def __init__(self, comparators: List[Comparator]):
        self.comparators = comparators

    def matches(self, v: Version) -> bool:
        # Prerelease rule: if the version has a prerelease, at least one comparator
        # in this set must have a version with the same MAJOR.MINOR.PATCH and a prerelease
        if v.prerelease is not None:
            has_matching_pre = False
            for c in self.comparators:
                if (c.version.prerelease is not None and
                    c.version.major == v.major and
                    c.version.minor == v.minor and
                    c.version.patch == v.patch):
                    has_matching_pre = True
                    break
            if not has_matching_pre:
                return False

        for c in self.comparators:
            if not c.matches(v):
                return False
        return True


def _expand_comparator(op: str, s: str) -> List[Comparator]:
    """Expand a single comparator string into one or more Comparator objects."""
    major, minor, patch, prerelease, is_exact = _parse_partial_version(s)

    # Handle tilde and caret separately
    if op == '~':
        return _expand_tilde(major, minor, patch, prerelease)
    elif op == '^':
        return _expand_caret(major, minor, patch, prerelease)

    # For regular operators or no operator
    if major is None:
        # X-range with no major: matches anything
        if op in ('', '='):
            return []  # Empty list means match all
        elif op == '<':
            return [Comparator('<', Version(0, 0, 0))]
        elif op == '<=':
            return [Comparator('<', Version(1, 0, 0))]
        elif op == '>':
            return []  # Matches anything (since no version is > all)
            # Actually, >X matches everything since there's no upper bound
            # Let me reconsider...
        elif op == '>=':
            return []

    if major is not None and minor is None:
        # X in minor position
        if op in ('', '='):
            # 1.x means >=1.0.0 <2.0.0
            return [Comparator('>=', Version(major, 0, 0)),
                    Comparator('<', Version(major + 1, 0, 0))]
        elif op == '>':
            # >1 means >=2.0.0
            return [Comparator('>=', Version(major + 1, 0, 0))]
        elif op == '<':
            # <1 means <1.0.0
            return [Comparator('<', Version(major, 0, 0))]
        elif op == '>=':
            # >=1 means >=1.0.0
            return [Comparator('>=', Version(major, 0, 0))]
        elif op == '<=':
            # <=1 means <2.0.0
            return [Comparator('<', Version(major + 1, 0, 0))]

    if major is not None and minor is not None and patch is None:
        # X in patch position
        if op in ('', '='):
            # 1.2.x means >=1.2.0 <1.3.0
            return [Comparator('>=', Version(major, minor, 0)),
                    Comparator('<', Version(major, minor + 1, 0))]
        elif op == '>':
            # >1.2 means >=1.3.0
            return [Comparator('>=', Version(major, minor + 1, 0))]
        elif op == '<':
            # <1.2 means <1.2.0
            return [Comparator('<', Version(major, minor, 0))]
        elif op == '>=':
            # >=1.2 means >=1.2.0
            return [Comparator('>=', Version(major, minor, 0))]
        elif op == '<=':
            # <=1.2 means <1.3.0
            return [Comparator('<', Version(major, minor + 1, 0))]

    if is_exact:
        ver = Version(major, minor, patch, prerelease)
        if op in ('', '='):
            return [Comparator('=', ver)]
        elif op == '>':
            return [Comparator('>', ver)]
        elif op == '<':
            return [Comparator('<', ver)]
        elif op == '>=':
            return [Comparator('>=', ver)]
        elif op == '<=':
            return [Comparator('<=', ver)]

    raise ValueError(f"Invalid comparator: {op}{s}")


def _expand_tilde(major, minor, patch, prerelease) -> List[Comparator]:
    """Expand tilde range."""
    if major is None:
        # ~X matches anything
        return []
    elif minor is None:
        # ~1 means >=1.0.0 <2.0.0
        lower = Version(major, 0, 0)
        upper = Version(major + 1, 0, 0)
        return [Comparator('>=', lower), Comparator('<', upper)]
    elif patch is None:
        # ~1.2 means >=1.2.0 <1.3.0
        lower = Version(major, minor, 0)
        upper = Version(major, minor + 1, 0)
