                has_content = True
                i = new_i

            else:
                # Regular character
                segments.append((c, False))
                has_content = True
                i += 1

        if not has_content:
            continue

        # Now process the word with field splitting for unquoted expansions
        # We need to build the final words from this segment list.
        # Quoted parts are kept together. Unquoted expansion results are split on whitespace.

        result_words = []
        current_word_parts = []  # list of strings that form the current word

        for text, is_unq_exp in segments:
            if is_unq_exp:
                # Split this expansion result on whitespace
                parts = re.split(r'[ \t\n]+', text)
                # If the entire word so far plus this expansion would produce empty words, handle that
                for part in parts:
                    if current_word_parts:
                        # Append to current word
                        current_word_parts.append(part)
                        result_words.append(''.join(current_word_parts))
                        current_word_parts = []
                    elif part != '':
                        # Start a new word with this part
                        current_word_parts.append(part)
                # If current_word_parts is non-empty and we have more segments, 
                # the next segment will be appended to it
            else:
                # Quoted or literal text - append directly
                if not text:
                    continue
                if current_word_parts:
                    current_word_parts.append(text)
                else:
                    current_word_parts.append(text)

        # Flush any remaining current word
        if current_word_parts:
            final = ''.join(current_word_parts)
            result_words.append(final)

        # Filter out empty words that were entirely from unquoted expansions
        # But keep empty words that came from quoted parts ("" or '')
        filtered = []
        for w in result_words:
            if w == '':
                # Check if this word was entirely from an unquoted expansion
                # If it has any quoted content, keep it; otherwise remove it
                # Actually, a simpler heuristic: if the original segments had no quoted parts 
                # contributing to this empty word, remove it.
                # For now, let's check: if has_quoted_part is False and the word is empty, remove it.
                # But we need to be more careful - an empty word could come from a mix.
                # Let's just keep it if there was any quoted part in the original word construction.
                if not has_quoted_part:
                    continue
            filtered.append(w)

        words.extend(filtered)

    return words


def _expand(line: str, i: int, env: dict[str, str]) -> tuple[str, int]:
    """Expand a $ at position i. Returns (expanded_string, new_position)."""
    n = len(line)
    if i + 1 >= n:
        # Trailing $ with nothing after it - literal $
        return '$', i + 1

    c = line[i + 1]

    if c == '{':
        # ${NAME}, ${NAME:-default}, ${NAME-default}
        j = i + 2  # position after ${
        # Find the closing }
        depth = 1
        k = j
        while k < n and depth > 0:
            if line[k] == '{':
                depth += 1
            elif line[k] == '}':
                depth -= 1
            k += 1
        if depth != 0:
            raise ValueError("unterminated ${")
        inner = line[j:k-1]  # content between ${ and }
        new_i = k

        # Parse the inner expression
        colon_dash_idx = inner.find(':-')
        dash_idx = inner.find('-')

        if colon_dash_idx != -1:
            name = inner[:colon_dash_idx]
            default_text = inner[colon_dash_idx+2:]
            if not _is_valid_name(name):
                raise ValueError(f"invalid variable name: {name}")
            value = env.get(name)
            if value is None or value == '':
                result = _expand_string(default_text, env)
            else:
                result = value
            return result, new_i

        elif dash_idx != -1:
            name = inner[:dash_idx]
            default_text = inner[dash_idx+1:]
            if not _is_valid_name(name):
                raise ValueError(f"invalid variable name: {name}")
            value = env.get(name)
            if value is None:
                result = _expand_string(default_text, env)
            else:
                result = value
            return result, new_i

        else:
            # Just ${NAME}
            name = inner
            if not _is_valid_name(name):
                raise ValueError(f"invalid variable name: {name}")
            value = env.get(name, '')
            return value, new_i

    elif c.isalpha() or c == '_':
        # $NAME - longest match of [A-Za-z_][A-Za-z0-9_]*
        j = i + 1
        while j < n and (line[j].isalnum() or line[j] == '_'):
            j += 1
        name = line[i+1:j]
        value = env.get(name, '')
        return value, j

    else:
        # $ not followed by name or { is literal
        return '$', i + 1


def _is_valid_name(name: str) -> bool:
    if not name:
        return False
    if not (name[0].isalpha() or name[0] == '_'):
        return False
    for ch in name:
        if not (ch.isalnum() or ch == '_'):
            return False
    return True


def _expand_string(text: str, env: dict[str, str]) -> str:
    """Expand $ variables in a string (for default values)."""
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '$':
            expanded, new_i = _expand(text, i, env)
            result.append(expanded)
            i = new_i
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)
