from __future__ import annotations

import typing
from dataclasses import fields, is_dataclass, MISSING, Field
from typing import get_type_hints, Literal


class LoadError(ValueError):
    def __init__(self, path: str, message: str = ""):
        self.path = path
        if message:
            super().__init__(f"{path}: {message}")
        else:
            super().__init__(f"{path}: invalid value")

    def __str__(self) -> str:
        return f"{self.path}: {self._msg}" if hasattr(self, '_msg') else super().__str__()


def _make_error(path: str, msg: str = "") -> LoadError:
    e = LoadError.__new__(LoadError)
    e.path = path
    e._msg = msg
    ValueError.__init__(e, f"{path}: {msg}" if msg else f"{path}: invalid value")
    return e


def _resolve_annotation(cls, field_name: str):
    """Resolve the type annotation for a field of cls."""
    try:
        hints = get_type_hints(cls)
        if field_name in hints:
            return hints[field_name]
    except Exception:
        pass
    # Fallback: look at __annotations__ directly
    anns = getattr(cls, '__annotations__', {})
    if field_name in anns:
        val = anns[field_name]
        if isinstance(val, str):
            # Try to resolve the string annotation
            try:
                return eval(val, {'__builtins__': {}, **typing.__dict__, 'Literal': Literal})
            except Exception:
                return val
        return val
    raise LoadError(f"$.{field_name}", "cannot resolve annotation")


def _load_value(data, typ, path: str):
    """Load a value from data according to type annotation typ. Raise LoadError on failure."""

    # Handle NoneType
    if typ is type(None) or typ is None:
        if data is None:
            return None
        raise _make_error(path, f"expected null, got {type(data).__name__}")

    # Handle Optional[T] (i.e., T | None)
    optional_inner = _get_optional_inner(typ)
    if optional_inner is not None:
        if data is None:
            return None
        # Non-null data: load as the inner type, errors propagate with same path
        return _load_value(data, optional_inner, path)

    # Handle Literal[...]
    literal_args = _get_literal_args(typ)
    if literal_args is not None:
        for lit in literal_args:
            if data == lit and type(data) is type(lit):
                return data
        raise _make_error(path, f"expected one of {literal_args}, got {data!r}")

    # Handle Union (non-Optional unions like int | str)
    union_args = _get_union_args(typ)
    if union_args is not None:
        for arg in union_args:
            try:
                return _load_value(data, arg, path)
            except LoadError:
                continue
        raise _make_error(path, f"no union member matched for {data!r}")

    # Handle list[T]
    list_inner = _get_list_inner(typ)
    if list_inner is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list, got {type(data).__name__}")
        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item, list_inner, item_path))
        return result

    # Handle dict[str, T]
    dict_inner = _get_dict_inner(typ)
    if dict_inner is not None:
        if not isinstance(data, dict):
            raise _make_error(path, f"expected dict, got {type(data).__name__}")
        result = {}
        for key, val in data.items():
            key_path = f"{path}.{key}"
            result[key] = _load_value(val, dict_inner, key_path)
        return result

    # Handle tuple[T, ...] (variable length)
    tuple_varargs = _get_tuple_varargs(typ)
    if tuple_varargs is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list for tuple, got {type(data).__name__}")
        result = []
        for i, item in enumerate(data):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item, tuple_varargs, item_path))
        return tuple(result)

    # Handle fixed-length tuple[A, B, C]
    tuple_fixed = _get_tuple_fixed(typ)
    if tuple_fixed is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list for tuple, got {type(data).__name__}")
        if len(data) != len(tuple_fixed):
            raise _make_error(path, f"expected tuple of length {len(tuple_fixed)}, got list of length {len(data)}")
        result = []
        for i, (item, sub_typ) in enumerate(zip(data, tuple_fixed)):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item, sub_typ, item_path))
        return tuple(result)

    # Handle bool
    if typ is bool:
        if isinstance(data, bool):
            return data
        raise _make_error(path, f"expected bool, got {type(data).__name__}")

    # Handle int (bool not accepted)
    if typ is int:
        if isinstance(data, bool):
            raise _make_error(path, f"expected int, got bool")
        if isinstance(data, int):
            return data
        raise _make_error(path, f"expected int, got {type(data).__name__}")

    # Handle float (int accepted and converted, bool not)
    if typ is float:
        if isinstance(data, bool):
            raise _make_error(path, f"expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise _make_error(path, f"expected float, got {type(data).__name__}")

    # Handle str
    if typ is str:
        if isinstance(data, str):
            return data
        raise _make_error(path, f"expected str, got {type(data).__name__}")

    # Handle nested dataclass
    if isinstance(typ, type) and is_dataclass(typ):
        if not isinstance(data, dict):
            raise _make_error(path, f"expected dict for dataclass {typ.__name__}, got {type(data).__name__}")
        return _load_dataclass_instance(typ, data, path)

    # Unknown type - try to see if it's something we can handle
    raise _make_error(path, f"unsupported type annotation: {typ!r}")


def _load_dataclass_instance(cls, data: dict, path: str):
    """Build an instance of dataclass cls from dict data."""

    # Get field hints
    try:
        hints = get_type_hints(cls)
    except Exception as e:
        raise _make_error(path, f"cannot resolve type hints for {cls.__name__}: {e}")

    # Get all fields
    cls_fields = fields(cls)
    field_map = {f.name: f for f in cls_fields}

    # Check for unknown keys
    for key in data.keys():
        if key not in field_map:
            raise _make_error(f"{path}.{key}", "unknown field")

    # Build kwargs
    kwargs = {}
    for f in cls_fields:
        name = f.name
        if name in data:
            val = data[name]
            field_path = f"{path}.{name}"
            typ = hints.get(name, type(None))
            kwargs[name] = _load_value(val, typ, field_path)
        else:
            # Missing key - use default or default_factory
            if f.default is not MISSING:
                kwargs[name] = f.default
            elif f.default_factory is not MISSING:
                kwargs[name] = f.default_factory()
            else:
                raise _make_error(f"{path}.{name}", "missing required field")

    return cls(**kwargs)


def _get_optional_inner(typ):
    """If typ is Optional[T] (i.e., Union[T, None]), return T. Otherwise return None."""
    args = typing.get_args(typ)
    if len(args) == 2 and type(None) in args:
        for a in args:
            if a is not type(None):
                return a
    # Also handle the case where Optional is represented differently
    if hasattr(typ, '__origin__') and typ.__origin__ is typing.Union:
        args = typing.get_args(typ)
        if len(args) == 2 and type(None) in args:
            for a in args:
                if a is not type(None):
                    return a
    return None


def _get_union_args(typ):
    """If typ is a Union with more than 2 args (or exactly 2 but neither is None), return the args. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is typing.Union:
        args = typing.get_args(typ)
        # If it's Optional (contains NoneType with 2 args), we handle that separately
        if len(args) == 2 and type(None) in args:
            return None  # Handled by _get_optional_inner
        return args
    return None


def _get_literal_args(typ):
    """If typ is Literal[...], return the tuple of literal values. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is Literal:
        return typing.get_args(typ)
    # Python 3.8+ might represent it differently
    if hasattr(typ, '__args__') and hasattr(typ, '__origin__'):
        pass
    return None


def _get_list_inner(typ):
    """If typ is list[T], return T. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is list:
        args = typing.get_args(typ)
        if len(args) == 1:
            return args[0]
    return None


def _get_dict_inner(typ):
    """If typ is dict[str, T], return T. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is dict:
        args = typing.get_args(typ)
        if len(args) == 2:
            # First arg should be str, second is the value type
            key_type, val_type = args
            if key_type is str:
                return val_type
            # Accept any dict for simplicity, but spec says dict[str, T]
            return val_type
    return None


def _get_tuple_varargs(typ):
    """If typ is tuple[T, ...], return T. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is tuple:
        args = typing.get_args(typ)
        if len(args) == 2 and args[1] is Ellipsis:
            return args[0]
    return None


def _get_tuple_fixed(typ):
    """If typ is a fixed-length tuple like tuple[A, B, C], return the tuple of types. Otherwise return None."""
    origin = getattr(typ, '__origin__', None)
    if origin is tuple:
        args = typing.get_args(typ)
        if len(args) >= 1 and (len(args) == 1 or args[-1] is not Ellipsis):
            # If it's tuple[T, ...], handled by _get_tuple_varargs
            if len(args) == 2 and args[1] is Ellipsis:
                return None
            return args
    return None


def load(cls, data):
    """Build an instance of dataclass type cls from JSON-like data."""
    if not (isinstance(cls, type) and is_dataclass(cls)):
        raise LoadError("$", f"cls must be a dataclass type, got {cls!r}")
    return _load_value(data, cls, "$")
```

The key issues:
1. **Union detection**: With `from __future__ import annotations`, `str | int` evaluates to `types.UnionType` (PEP 604), not `typing.Union`. Need to handle both.
2. **Dict value path for unions**: When a dict value fails to load against a union type, the error path should point at the *key* (`$.servers[0].tags.bad`), not propagate deep into the value's internal structure. The fix: catch `LoadError` from `_load_value` on dict values and re-raise with the key path.

```python
from __future__ import annotations

import typing
from types import UnionType as _UnionType
from dataclasses import fields, is_dataclass, MISSING
from typing import get_type_hints, Literal


class LoadError(ValueError):
    def __init__(self, path: str, message: str = ""):
        self.path = path
        msg = f"{path}: {message}" if message else f"{path}: invalid value"
        super().__init__(msg)

    def __str__(self) -> str:
        return super().__str__()


def _make_error(path: str, msg: str = "") -> LoadError:
    return LoadError(path, msg)


def load(cls, data):
    """Build an instance of dataclass type cls from JSON-like data."""
    if not (isinstance(cls, type) and is_dataclass(cls)):
        raise _make_error("$", f"cls must be a dataclass type, got {cls!r}")
    return _load_value(data, cls, "$")


def _load_value(data, typ, path: str):
    """Load a value from data according to type annotation typ. Raise LoadError on failure."""

    # NoneType
    if typ is type(None):
        if data is None:
            return None
        raise _make_error(path, f"expected null, got {type(data).__name__}")

    # Optional[T] / T | None (exactly two members, one is None)
    optional_inner = _get_optional_inner(typ)
    if optional_inner is not None:
        if data is None:
            return None
        return _load_value(data, optional_inner, path)

    # Literal[...]
    lit_args = _get_literal_args(typ)
    if lit_args is not None:
        for lit in lit_args:
            if data == lit and type(data) is type(lit):
                return data
        raise _make_error(path, f"expected one of {lit_args}, got {data!r}")

    # Union (non-Optional, e.g. int | str)
    union_args = _get_union_args(typ)
    if union_args is not None:
        for arg in union_args:
            try:
                return _load_value(data, arg, path)
            except LoadError:
                continue
        raise _make_error(path, f"no union member matched for {data!r}")

    # list[T]
    li = _get_list_inner(typ)
    if li is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list, got {type(data).__name__}")
        result = []
        for i, item in enumerate(data):
            result.append(_load_value(item, li, f"{path}[{i}]"))
        return result

    # dict[str, T]
    di = _get_dict_inner(typ)
    if di is not None:
        if not isinstance(data, dict):
            raise _make_error(path, f"expected dict, got {type(data).__name__}")
        result = {}
        for key, val in data.items():
            try:
                result[key] = _load_value(val, di, f"{path}.{key}")
            except LoadError:
                raise _make_error(f"{path}.{key}", "invalid value")
        return result

    # tuple[T, ...] (variable-length)
    tv = _get_tuple_varargs(typ)
    if tv is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list for tuple, got {type(data).__name__}")
        result = []
        for i, item in enumerate(data):
            result.append(_load_value(item, tv, f"{path}[{i}]"))
        return tuple(result)

    # tuple[A, B, C] (fixed-length)
    tf = _get_tuple_fixed(typ)
    if tf is not None:
        if not isinstance(data, list):
            raise _make_error(path, f"expected list for tuple, got {type(data).__name__}")
        if len(data) != len(tf):
            raise _make_error(path, f"expected tuple of length {len(tf)}, got list of length {len(data)}")
        result = []
        for i, (item, sub) in enumerate(zip(data, tf)):
            result.append(_load_value(item, sub, f"{path}[{i}]"))
        return tuple(result)

    # bool (before int, since bool is a subclass of int)
    if typ is bool:
        if isinstance(data, bool):
            return data
        raise _make_error(path, f"expected bool, got {type(data).__name__}")

    # int (bool not accepted)
    if typ is int:
        if isinstance(data, bool):
            raise _make_error(path, "expected int, got bool")
        if isinstance(data, int):
            return data
        raise _make_error(path, f"expected int, got {type(data).__name__}")

    # float (int accepted and converted, bool not)
    if typ is float:
        if isinstance(data, bool):
            raise _make_error(path, "expected float, got bool")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise _make_error(path, f"expected float, got {type(data).__name__}")

    # str
    if typ is str:
        if isinstance(data, str):
            return data
        raise _make_error(path, f"expected str, got {type(data).__name__}")

    # Nested dataclass
    if isinstance(typ, type) and is_dataclass(typ):
        if not isinstance(data, dict):
            raise _make_error(path, f"expected dict for dataclass {typ.__name__}, got {type(data).__name__}")
        return _load_dataclass_instance(typ, data, path)

    raise _make_error(path, f"unsupported type annotation: {typ!r}")


def _load_dataclass_instance(cls, data: dict, path: str):
    """Build an instance of dataclass cls from dict data."""
    try:
        hints = get_type_hints(cls)
    except Exception as e:
        raise _make_error(path, f"cannot resolve type hints for {cls.__name__}: {e}")

    cls_fields = fields(cls)
    field_map = {f.name: f for f in cls_fields}

    # Check for unknown keys (first one in input dict order)
    for key in data.keys():
        if key not in field_map:
            raise _make_error(f"{path}.{key}", "unknown field")

    kwargs = {}
    for f in cls_fields:
        name = f.name
        if name in data:
            typ = hints.get(name, type(None))
            kwargs[name] = _load_value(data[name], typ, f"{path}.{name}")
        else:
            if f.default is not MISSING:
                kwargs[name] = f.default
            elif f.default_factory is not MISSING:
                kwargs[name] = f.default_factory()
            else:
                raise _make_error(f"{path}.{name}", "missing required field")

    return cls(**kwargs)


def _get_optional_inner(typ):
    """If typ is Optional[T] (Union with exactly 2 args, one being NoneType), return T. Else None."""
    if not isinstance(typ, type):
        origin = getattr(typ, "__origin__", None)
        if origin in (typing.Union, _UnionType):
            args = typing.get_args(typ)
            if len(args) == 2 and type(None) in args:
                for a in args:
                    if a is not type(None):
                        return a
    return None


def _get_union_args(typ):
    """If typ is a Union with >1 args (not the Optional case), return the args tuple. Else None."""
    if not isinstance(typ, type):
        origin = getattr(typ, "__origin__", None)
        if origin in (typing.Union, _UnionType):
            args = typing.get_args(typ)
            # Exclude the Optional case (2 args with NoneType)
            if len(args) == 2 and type(None) in args:
                return None
            return args
    return None


def _get_literal_args(typ):
    """If typ is Literal[...], return the tuple of literal values. Else None."""
    origin = getattr(typ, "__origin__", None)
    if origin is Literal:
        return typing.get_args(typ)
    return None


def _get_list_inner(typ):
    """If typ is list[T], return T. Else None."""
    origin = getattr(typ, "__origin__", None)
    if origin is list:
        args = typing.get_args(typ)
        if len(args) == 1:
            return args[0]
    return None


def _get_dict_inner(typ):
    """If typ is dict[str, T], return T. Else None."""
    origin = getattr(typ, "__origin__", None)
    if origin is dict:
        args = typing.get_args(typ)
        if len(args) == 2:
            return args[1]
    return None


def _get_tuple_varargs(typ):
    """If typ is tuple[T, ...], return T. Else None."""
    origin = getattr(typ, "__origin__", None)
    if origin is tuple:
        args = typing.get_args(typ)
        if len(args) == 2 and args[1] is Ellipsis:
            return args[0]
    return None


def _get_tuple_fixed(typ):
    """If typ is a fixed-length tuple like tuple[A, B, C], return the types. Else None."""
    origin = getattr(typ, "__origin__", None)
    if origin is tuple:
        args = typing.get_args(typ)
        # Exclude variable-length case
        if len(args) == 2 and args[1] is Ellipsis:
            return None
        if len(args) >= 1:
            return args
    return None
