        printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
        exit 1
    }

    eqpos = index(line, "=")
    key = substr(line, 1, eqpos - 1)
    valpart = substr(line, eqpos + 1)

    if (key !~ /^[A-Za-z_][A-Za-z0-9_]*$/) {
        printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
        exit 1
    }

    # Empty value is valid (unquoted empty)
    if (valpart == "") {
        emit(key, "")
        next
    }

    firstchar = substr(valpart, 1, 1)

    if (firstchar == "'\''") {
        rest = substr(valpart, 2)
        closepos = index(rest, "'\''")
        if (closepos == 0) {
            printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
            exit 1
        }
        val = substr(rest, 1, closepos - 1)
        after = substr(rest, closepos + 1)
        if (after !~ /^[[:space:]]*(#.*)?$/) {
            printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
            exit 1
        }
        emit(key, val)
        next

    } else if (firstchar == "\"") {
        rest = substr(valpart, 2)
        in_str = ""
        i = 1
        len = length(rest)
        closed = 0
        while (i <= len) {
            c = substr(rest, i, 1)
            if (c == "\\") {
                if (i < len) {
                    nc = substr(rest, i + 1, 1)
                    if (nc == "n") {
                        in_str = in_str "\n"
                        i += 2
                        continue
                    } else if (nc == "\"") {
                        in_str = in_str "\""
                        i += 2
                        continue
                    } else if (nc == "\\") {
                        in_str = in_str "\\"
                        i += 2
                        continue
                    } else {
                        in_str = in_str "\\" nc
                        i += 2
                        continue
                    }
                } else {
                    break
                }
            } else if (c == "\"") {
                closed = 1
                i++
                break
            } else {
                in_str = in_str c
                i++
            }
        }

        if (!closed) {
            printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
            exit 1
        }

        after = substr(rest, i)
        if (after !~ /^[[:space:]]*(#.*)?$/) {
            printf "%s:%d: invalid line\n", filename, lineno > "/dev/stderr"
            exit 1
        }

        emit(key, in_str)
        next

    } else {
        # Unquoted value: taken literally up to " #" (space then hash)
        val = ""
        i = 1
        len = length(valpart)
        while (i <= len) {
            c = substr(valpart, i, 1)
            if (c == "#" && i > 1 && substr(valpart, i - 1, 1) == " ") {
                break
            }
            val = val c
            i++
        }
        sub(/[ \t]+$/, "", val)
        emit(key, val)
        next
    }
}
' "$FILE")
rc=$?

if [ $rc -ne 0 ]; then
    exit 1
fi

# Now handle duplicate keys: later value wins but keeps its LATER position.
# We need to print each key once, at its last occurrence position.
# So we collect all lines, track the last index for each key, and output in order of first... 
# Wait: "the later value wins but keeps its LATER position (print it once, at its last occurrence)"
# This means: if B appears at line 2 and line 7, print it only at line 7's position.
# So we need to: for each key, remember the last line number where it appeared.
# Then output lines in order, but skip any line whose key's last occurrence is not this line.

if [ -z "$output" ]; then
    exit 0
fi

printf '%s\n' "$output" | awk '
{
    # Each line is: export KEY='value'
    # Extract key
    line = $0
    # Remove "export " prefix
    sub(/^export /, "", line)
    eqpos = index(line, "=")
    key = substr(line, 1, eqpos - 1)

    # Store this line and its position
    lines[NR] = $0
    keys[NR] = key

    # Track last occurrence of each key
    last[key] = NR
}
END {
    for (i = 1; i <= NR; i++) {
        if (last[keys[i]] == i) {
            print lines[i]
        }
    }
}
'

exit 0
